'use strict';

// MODULES //

var asinhf = require( '@stdlib/math-base-special-asinhf' );
var f32 = require( '@stdlib/number-float64-base-to-float32' );


// VARIABLES //

var ONE = f32( 1.0 );


// MAIN //

/**
* Computes the hyperbolic arccosecant of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} hyperbolic arccosecant
*
* @example
* var v = acschf( 0.0 );
* // returns Infinity
*
* @example
* var v = acschf( -1.0 );
* // returns ~-0.881
*
* @example
* var v = acschf( 1.0 );
* // returns ~0.881
*/
function acschf( x ) {
	return asinhf( f32( ONE/f32( x ) ) );
}


// EXPORTS //

module.exports = acschf;
